('MCD-00040', 1, 'A revisar: The first book printed by means of whole pages of carved woodblock appeared in 868 ce...', 'Produção do exemplar datado do Sutra do Diamante por xilografia', 868, 868, '11 de maio de 868 (exemplar conservado; a técnica é anterior)', 'artefato editorial / técnica de impressão', 124, 137, 'IDENTIFICADO_PRELIMINARMENTE', 'PENDENTE_DE_EVIDENCIAS', 'NAO_REVISADO', 0, '["Separar pontuação do artefato preservado da avaliação da invenção ou difusão da xilografia.", "Documentar difusão, persistência e aperfeiçoamentos com recorte definido."]', '{"id_extracao": "MCD-00040", "titulo_original_planilha": "A revisar: The first book printed by means of whole pages of carved woodblock appeared in 868 ce...", "titulo_proposto": "Produção do exemplar datado do Sutra do Diamante por xilografia", "ano_original": 868, "ano_validado": 868, "periodo_historico_proposto": "11 de maio de 868 (exemplar conservado; a técnica é anterior)", "categoria_original_sql": null, "categoria_proposta": "artefato editorial / técnica de impressão", "pagina_livro": 124, "pagina_pdf": 137, "situacao_identificacao": "IDENTIFICADO_PRELIMINARMENTE", "analise_historica": {"o_que_aconteceu": "Exemplar chinês completo da Sutra do Diamante impresso com matrizes de madeira e colofão datado, conservado em Londres.", "problema_resolvido": "Reproduzir textos e imagens sem copiar cada exemplar manualmente.", "transformacao": "Prova material de técnica sofisticada de impressão já operacional em 868.", "consequencias_posteriores": "Exemplifica uma indústria impressora com usos religiosos e, no período, também administrativos.", "limitacoes_controversias": "Não representar o ano de 868 como a data da invenção da xilografia; alcance da tecnologia e do exemplar devem ser separados."}, "matriz_criterios": {"impacto_difusao": {"nota": null, "situacao": "SEM_EVIDENCIA", "justificativa": "O exemplar não comprova sozinho a difusão ampla da técnica à época.", "evidencias_utilizadas": ["D1: Registro do 